import PyPDF2


class PDFHandler:
    def __init__(self, filepaths):
        self._filepaths = filepaths
        self.readers = [PyPDF2.PdfReader(fp) for fp in filepaths]

    def get_filepaths(self):
        return self._filepaths

    def set_filepaths(self, filepaths):
        self._filepaths = filepaths
        self.readers = [PyPDF2.PdfReader(fp) for fp in filepaths]

    def merge_pdfs(self, output_filepath):
        pdf_writer = PyPDF2.PdfWriter()

        for reader in self.readers:
            self._add_pages_to_writer(reader, pdf_writer)

        with open(output_filepath, 'wb') as out:
            pdf_writer.write(out)
        return f"Merged PDFs saved at {output_filepath}"

    def _add_pages_to_writer(self, reader, pdf_writer):
        for page_num in range(len(reader.pages)):
            page = reader.pages[page_num]
            pdf_writer.add_page(page)

    def extract_text_from_pdfs(self):
        pdf_texts = []
        for reader in self.readers:
            pdf_texts.extend(self._extract_text_from_reader(reader))
        return pdf_texts

    def _extract_text_from_reader(self, reader):
        extracted_texts = []
        for page_num in range(len(reader.pages)):
            page = reader.pages[page_num]
            extracted_texts.append(page.extract_text())
        return extracted_texts
